// EXT05 «Энциклопедия функций: текст, даты и финансы» — дополнительный модуль курса «Бухгалтерия» (сверх ТЗ).
// Уроки Ф18–Ф31 и Ф33 из docs/courses/accounting/functions-audit.md (раздел 6).
// Все значения в примерах и вопросах посчитаны на Python независимо (scratchpad x05/calc.py), а не в Excel:
// Excel у автора курса нет. Данные вымышленные. Русские имена функций — как в интерфейсе русского Excel
// (docs/courses/accounting/excel-compatibility.md); на страницах Microsoft часть имён переведена машинно.
import { p, qq, qmatch, qtf, qfill, qnum, qtable, qgap, hard } from '../lessonAuthoring'
import type { HomeworkQuizQuestion } from '../lessonContent'
import { excelSheet, formulaFig } from './accFigures'
import type { FormulaPart, ExcelSheetOpts } from './accFigures'
import type { AccModule, AccLesson, AccSource } from './types'

const CHECKED = '2026-11-27'
const NEED = 'Excel для Windows (версии — в абзаце «В какой версии Excel»); учебный файл не нужен — все данные вымышленные и приведены в уроке, набирайте их на чистом листе. Файл с расчётом: «Файл → Создать → Пустая книга».'
const SAFE = 'Рабочие выгрузки для тренировки обезличьте: уберите ФИО, ИНН, счета, названия контрагентов. Отправлять данные организации во внешние сервисы (в том числе ИИ) можно только по решению работодателя и ИТ.'

/** Схема «формула по частям». */
interface Fig { title: string; parts: FormulaPart[]; steps: Array<[string, string]>; caption: string }
/** Лист Excel с результатом. */
interface Sheet { title: string; rows: string[][]; opts: ExcelSheetOpts; caption: string; eq: string[] }
interface Spec {
  key: string; title: string; topics: string[]; minutes: number; practice: string; software: string; applies: string
  sources: string[]; queries: string[]; open: string[]
  task: string; when: string; need?: string
  args: string[]; figs: Fig[]; sheet: Sheet; ex: string
  steps: string[]; formula: string; eng: string
  why: string; was: string; trainer: string; work: string[]; mistakes: string[]; hint: string
  choose?: string; compat: string; ms: string; check: string; ai: string; src: string
  quiz: HomeworkQuizQuestion[]; hard: ReturnType<typeof hard>
}

const lines = (xs: string[]) => xs.map(x => `— ${x}`).join('\n')

function lesson(s: Spec): AccLesson {
  const paras = [
    p('task', `**Вопрос из работы.** ${s.task}`),
    p('when', `**Когда нужно и что получится.** ${s.when}`),
    p('need', `**Что нужно.** ${s.need ?? NEED}`),
    p('args', `**Синтаксис и аргументы.**\n${s.args.join('\n')}`),
    ...s.figs.map((f, i) => ({ id: `fig${i + 1}`, text: f.caption, image: formulaFig(f.title, f.parts, f.steps) })),
    p('ex', `**Исходный пример.** ${s.ex}\n${lines(s.sheet.eq)}`),
    { id: 'sheet', text: s.sheet.caption, image: excelSheet(s.sheet.title, s.sheet.rows, s.sheet.opts) },
    p('steps', s.steps.map((t, i) => `**Шаг ${i + 1}.** ${t}`).join('\n')),
    p('formula', `**Формула.**\n\`${s.formula}\`\nАнгл.: \`${s.eng}\``),
    p('why', `**Почему работает.** ${s.why}`),
    p('was', `**Было → стало.** ${s.was}`),
    p('trainer', `**Поменяйте и проверьте.** ${s.trainer}`),
    p('work', `**В бухгалтерской работе.**\n${lines(s.work)}`),
    p('mist', `**Типичные ошибки.**\n${lines(s.mistakes)}`),
    p('hint', `**Подсказка.** ${s.hint}`),
    ...(s.choose ? [p('choose', `**Какой способ выбрать.** ${s.choose}`)] : []),
    p('compat', `**В какой версии Excel.** ${s.compat}`),
    p('ms', `**Microsoft.** ${s.ms}`),
    p('check', `**Проверка себя.** ${s.check}`),
    p('ai', `**Быстрее с ИИ.** ${s.ai} ${SAFE}`),
    p('src', `Источники: ${s.src}`),
  ]
  return {
    key: s.key, title: s.title, topics: s.topics, origin: [], minutes: s.minutes, practice: s.practice,
    software: s.software, applies: s.applies, sources: s.sources, queries: s.queries, open: s.open,
    content: { paragraphs: paras, quiz: s.quiz, hardTask: s.hard },
  }
}

const fp = (text: string, label?: string): FormulaPart => ({ text, label })
const MSDATE = 'проверено 27.11.2026'
const AI_NOTE = 'Если в вашем Excel нет Copilot, вставьте запрос в чат с ИИ, который разрешил работодатель.'

