const L13 = lesson({
  key: 'x05-13', title: 'ПЛТ, ЧПС, ЧИСТНЗ: график платежей и дисконтирование',
  topics: ['ПЛТ', 'ЧПС', 'ЧИСТНЗ'], minutes: 40,
  practice: 'Чистый лист Excel; займ и отсрочка из урока (вымышленные)', software: 'Excel для Windows; финансовые функции, версии — в абзаце «В какой версии Excel»',
  applies: 'Расчётные функции; ставка и способ дисконтирования выбираются по договору и учётной политике',
  sources: ['ms-alpha', 'ms-pmt', 'ms-npv', 'ms-xnpv'],
  queries: ['аннуитетный платёж по займу Excel', 'ПЛТ даёт отрицательное число', 'дисконтирование отсрочки платежа', 'ЧПС и ЧИСТНЗ разница'],
  open: ['Урок m21-05 («Скидки, бонусы, отсрочка и рассрочка») — способ начисления процентов при отсрочке ФСБУ 9/2025 не задаёт; ставка 10 % годовых и сложный процент в примере учебные. Нормы стандарта в этом уроке не пересказываются.', 'ЧИСТНЗ: допущение «год = 365 дней» взято из документации Microsoft; проверить поведение в самом Excel не удалось.'],
  task: '«Займ 1 200 000 на 12 месяцев под 12 % годовых: каков ежемесячный платёж и график? А продажа с оплатой через два года 1 210 000 — сколько это сегодня при ставке 10 %?»',
  when: 'Когда надо рассчитать равный платёж по займу, составить график, или привести будущие платежи к сегодняшней стоимости (дисконтировать). Результат — число-платёж или приведённая стоимость.',
  args: [
    '**ПЛТ(ставка; кпер; пс; [бс]; [тип])** — платёж за период при равных платежах (аннуитет).',
    '— `ставка` — ставка за период: годовая ставка делится на число периодов (12 % годовых → 1 % в месяц). Обязательный.',
    '— `кпер` — число периодов выплат. Обязательный. `пс` — текущая сумма займа; обязательный.',
    '— `бс` — остаток после последнего платежа (по умолчанию 0); `тип` — 0 (по умолчанию) — платёж в конце периода, 1 — в начале.',
    'Платёж получается отрицательным (это исходящий денежный поток), если сумма займа `пс` положительна; чтобы получить положительный платёж, поставьте минус перед `пс`.',
    '**ЧПС(ставка; значение1; [значение2]; …)** — приведённая стоимость серии платежей, считая, что первый платёж — в конце первого периода; платежи через равные периоды.',
    '**ЧИСТНЗ(ставка; значения; даты)** — приведённая стоимость по датам; платежи могут идти неравными интервалами. Первая дата — начало графика (первый платёж не дисконтируется), остальные платежи дисконтируются на основе 365-дневного года. По странице Microsoft, ряд значений должен содержать хотя бы одно положительное и одно отрицательное значение; первый платёж, если это затраты, — отрицательный.',
  ],
  figs: [
    { title: 'ПЛТ: платёж по займу', parts: [fp('=ПЛТ('), fp('12%/12', '1: ставка за месяц: 12 % годовых делим на 12'), fp(';'), fp('12', '2: 12 платежей'), fp(';'), fp('-1200000', '3: сумма займа со знаком минус (чтобы платёж был положительным)'), fp(')')], steps: [['ставка за месяц', '1 % = 0,01'], ['1 200 000 × 0,01 / (1 − 1,01^-12)', '106 618,55']], caption: 'Схема 1. Платёж 106 618,55 ₽ в месяц: ставка делится на 12, число периодов — месяцы.' },
    { title: 'ЧПС: приведение отсрочки к сегодняшнему дню', parts: [fp('=ЧПС('), fp('10%', '1: ставка за период — год'), fp(';'), fp('0', '2: платёж в конце 1-го года — нет'), fp(';'), fp('1210000', '3: платёж в конце 2-го года')], steps: [['0 / 1,1', '0'], ['1 210 000 / 1,1²', '1 000 000'], ['сумма', '1 000 000']], caption: 'Схема 2. Платёж 1 210 000 через два года при 10 % годовых «стоит» сегодня 1 000 000 — как в уроке m21-05.' },
    { title: 'ЧИСТНЗ: те же платежи по датам', parts: [fp('=ЧИСТНЗ('), fp('10%', '1: ставка'), fp(';'), fp('{-1000000;1210000}', '2: платежи: −1 000 000 в начале, +1 210 000 через два года'), fp(';'), fp('{01.01.2027;01.01.2029}', '3: даты платежей')], steps: [['дней между датами', '731 (2028 — високосный)'], ['степень: 731/365', '2,00274'], ['1 210 000 / 1,1^2,00274', '999 738,91'], ['−1 000 000 + 999 738,91', '−261,09']], caption: 'Схема 3. ЧИСТНЗ считает по реальным дням: итог −261,09, а не 0, как дал бы ЧПС: високосный 2028 год добавил день.' },
  ],
  ex: 'Займ 1 200 000 ₽ на 12 месяцев под 12 % годовых (платёж в конце месяца) и продажа с оплатой 1 210 000 ₽ через 24 месяца при ставке 10 % годовых (учебный пример курса, урок m21-05).',
  sheet: { title: 'Учебная реконструкция: график платежей по займу', rows: [['Месяц', 'Платёж', 'Проценты', 'Основной долг', 'Остаток'], ['1', '106 618,55', '12 000,00', '94 618,55', '1 105 381,45'], ['2', '106 618,55', '11 053,81', '95 564,73', '1 009 816,72'], ['3', '106 618,55', '10 098,17', '96 520,38', '913 296,34']], opts: { formula: '=ПЛТ(12%/12;12;-1200000)', selected: [1, 1], result: [[1, 1]] }, caption: 'Схема 4. Учебная реконструкция листа: первые три строки графика (проверено программно).', eq: ['ПЛТ(12%/12;12;-1200000) → 106 618,55', 'Месяц 1: проценты 1 200 000 × 1 % = 12 000,00; основной долг 94 618,55; остаток 1 105 381,45', 'Месяц 2: проценты 11 053,81; долг 95 564,73; остаток 1 009 816,72', 'Месяц 3: проценты 10 098,17; долг 96 520,38; остаток 913 296,34', 'Проценты за весь срок: 12 × 106 618,55 − 1 200 000 ≈ 79 422,56', 'ЧПС(10%;0;1210000) → 1 000 000; ЧИСТНЗ(10%;{-1000000;1210000};{01.01.2027;01.01.2029}) → −261,09 (приведённая стоимость 1 210 000 равна 999 738,91)'] },
  steps: ['В B1 введите `=ПЛТ(12%/12;12;-1200000)`, Enter: получится 106 618,55.', 'Для графика: в A4 введите 1…, в C4 `=E3*12%/12` (проценты = остаток × ставка), в D4 `=B4-C4`, в E4 `=E3-D4`. Начальный остаток — E3 = 1200000.', 'Протяните строки до 12-го месяца; в конце остаток должен быть 0.', 'В B8 введите `=ЧПС(10%;0;1210000)` — получится 1 000 000.', 'В B9 введите `=ЧИСТНЗ(10%;D1:D2;E1:E2)`, где D1 = −1000000, D2 = 1210000, E1 = 01.01.2027, E2 = 01.01.2029 — получится −261,09 (то есть приведённая стоимость 1 210 000 — 999 738,91).'],
  formula: '=ПЛТ(12%/12;12;-1200000)', eng: '=PMT(12%/12,12,-1200000)',
  why: 'ПЛТ считает платёж так, чтобы за все периоды долг с процентами погасился ровно: в начале большая доля — проценты, к концу — основной долг. ЧПС делит каждый будущий платёж на (1 + ставка) в степени числа периодов — это и есть дисконтирование. ЧИСТНЗ делает то же по точным датам.',
  was: 'Было: «платёж ~100 тысяч» на глаз. Стало: платёж 106 618,55, таблица процентов и остатка, и приведённая стоимость отсрочки 1 000 000.',
  trainer: 'Измените срок с 12 на 24 месяца: `=ПЛТ(12%/12;24;-1200000)`. Платёж должен уменьшиться (примерно до 56 488,17). Затем в ЧПС поставьте ставку 8 %: приведённая стоимость 1 210 000/1,08² ≈ 1 037 379,97.',
  work: ['Отсрочка платежа по договору: выручка без отсрочки и проценты по ней (урок m21-05, значительный компонент финансирования — по ФСБУ 9/2025; ставку и способ в стандарте нужно выбирать и закреплять в учётной политике).', 'График погашения займа: проценты и основной долг по месяцам.'],
  mistakes: ['Подставить годовую ставку при помесячных платежах: `=ПЛТ(12%;12;-1200000)`. Исправление: `12%/12`.', 'Не обратить внимания на знак: ПЛТ вернула −106 618,55. Исправление: минус перед суммой займа.', 'Применить ЧПС к платежу, который в начале первого периода: ЧПС его дисконтирует. Исправление: добавить первый платёж отдельно.', 'ЧИСТНЗ с одинаковыми для всех платежей датами или датой не в формате «Дата»: #ЗНАЧ!/#ЧИСЛО!. Исправление: проверить даты.', 'Использовать ставку, не закреплённую договором или учётной политикой. Исправление: уточнить ставку.'],
  hint: 'Проверка графика: остаток после последнего месяца должен быть 0 (или копейки округления). Если не 0 — ставка за период или число периодов указаны неверно.',
  choose: 'Короткий расчёт — формулы ПЛТ/ЧПС. Нужен график с датами — ЧИСТНЗ и отдельная таблица. Excel 2007+: все три есть. Power Query и Python для этого не нужны. Для вашей задачи лучше формулы: проверяются калькулятором.',
  compat: 'ПЛТ, ЧПС, ЧИСТНЗ — финансовые функции; страницы Microsoft называют Excel 2016 и новее (2019, 2021, 2024, Microsoft 365); для 2007–2013 страницы версию не подтверждают, в самом Excel не проверялось. Запасной вариант без ЧИСТНЗ: ручная формула `=значение/(1+ставка)^((дата-дата0)/365)`. В Google Таблицах: PMT, NPV, XNPV. В Power Query встроенных финансовых функций нет — используйте формулы Excel.',
  ms: 'Страницы Microsoft открыты 27.11.2026: ПЛТ — support.microsoft.com/ru-ru/excel/functions/pmt-function; ЧПС — …/npv-function; ЧИСТНЗ — …/xnpv-function.',
  check: 'ПЛТ(12%/12;12;-1200000) = 106 618,55; проценты за месяц 1 = 12 000,00, основной долг 94 618,55, остаток 1 105 381,45; ЧПС(10%;0;1210000) = 1 000 000; ЧИСТНЗ(10%;{-1000000;1210000};{01.01.2027;01.01.2029}) = −261,09. Проверено программно (Python), в Excel не проверялось.',
  ai: 'Попросите ИИ: «Объясни по частям `=ПЛТ(12%/12;12;-1200000)` и составь график платежей по займу на 12 месяцев». Данные вымышленные.',
  src: 'Microsoft — ПЛТ, ЧПС, ЧИСТНЗ (ru-ru), проверено 27.11.2026; связь с уроком курса m21-05 (ФСБУ 9/2025, п. 30–31, как в самом уроке); расчёты проверены программно.',
  quiz: [
    qnum('acc-x05-13-q1', 'Чему равен платёж `=ПЛТ(12%/12;12;-1200000)`? Округлите до копеек.', '106618,55', '1 200 000 × 0,01 / (1 − 1,01^-12) = 106 618,55.', { unit: '₽', tol: 1 }),
    qtable('acc-x05-13-q2', 'Впишите первую строку графика по займу (платёж 106 618,55).', ['Месяц', 'Проценты', 'Основной долг', 'Остаток'], [['1', '12000', '94618,55', '1105381,45']], ['0,1', '0,2', '0,3'], 'Проценты — 1 200 000 × 1 % = 12 000; основной долг = платёж − проценты; остаток = долг − основной долг.'),
    qq('acc-x05-13-q3', 'Формула `=ПЛТ(12%;12;-1200000)` даёт слишком большой платёж. Что исправить?', ['Разделить ставку на 12: 12%/12', 'Заменить ПЛТ на ЧПС', 'Убрать минус перед суммой', 'Увеличить число периодов до 144'], 0, 'При помесячных платежах ставка тоже должна быть месячной; годовые 12 % подставлены как за месяц.'),
    qgap('acc-x05-13-q4', 'Соберите приведённую стоимость платежа 1 210 000 через 2 года при 10 %.', '=____(10%;0;1210000)', [[['ЧПС', 'ПЛТ', 'ЧИСТНЗ'], 0]], 'ЧПС дисконтирует платежи в конце периодов; первый период — год 1 (платёж 0), второй — год 2.'),
    qnum('acc-x05-13-q5', 'Чему равна приведённая стоимость `=ЧПС(10%;0;1210000)`?', '1000000', '1 210 000 / 1,1² = 1 000 000.', { unit: '₽', tol: 1 }),
    qtf('acc-x05-13-q6', 'Верно ли?', [['ПЛТ при положительной сумме займа возвращает отрицательный платёж.', 'T'], ['ЧПС считает первый платёж в начале первого периода.', 'F'], ['ЧИСТНЗ принимает платежи с неравными интервалами.', 'T']], 'ЧПС дисконтирует первый платёж на период; ЧИСТНЗ работает по датам.'),
  ],
  hard: hard('График займа и дисконтирование отсрочки', 'Постройте график платежей по займу (ставка, срок, сумма по вашему выбору), проверьте, что остаток в конце равен нулю. Отдельно рассчитайте приведённую стоимость отсроченного платежа через ЧПС и ЧИСТНЗ и объясните разницу в результате.', 'Проверяем: ставка за период, знак ПЛТ, остаток 0, разница ЧПС/ЧИСТНЗ.', 'График, формулы, вывод'),
})

